const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.textPlain || item.json.snippet || '';
  const subject = item.json.subject || '';

  // Extract failed email address
  const emailPatterns = [
    /(?:to|recipient|address)[:\s]+([\w.+-]+@[\w.-]+)/i,
    /([\w.+-]+@[\w.-]+)\s+(?:was not|could not|failed|rejected|bounced)/i,
    /<([\w.+-]+@[\w.-]+)>/
  ];

  let failedAddress = '';
  for (const pattern of emailPatterns) {
    const match = body.match(pattern);
    if (match) {
      failedAddress = match[1];
      break;
    }
  }

  // Classify bounce type
  const bodyLower = body.toLowerCase();
  let bounceType = 'unknown';
  if (bodyLower.includes('mailbox full') || bodyLower.includes('quota exceeded')) {
    bounceType = 'soft_bounce_full';
  } else if (bodyLower.includes('user unknown') || bodyLower.includes('does not exist') || bodyLower.includes('no such user')) {
    bounceType = 'hard_bounce_invalid';
  } else if (bodyLower.includes('blocked') || bodyLower.includes('spam') || bodyLower.includes('rejected')) {
    bounceType = 'hard_bounce_blocked';
  } else if (bodyLower.includes('temporary') || bodyLower.includes('try again')) {
    bounceType = 'soft_bounce_temp';
  }

  results.push({
    json: {
      failedAddress: failedAddress,
      bounceType: bounceType,
      originalSubject: subject,
      snippet: body.substring(0, 300),
      detectedAt: new Date().toISOString(),
      action: bounceType.startsWith('hard') ? 'remove_from_list' : 'retry_later'
    }
  });
}
return results;

